class File {
  constructor(public name: string, public size: number) {}
}
class Folder {
  constructor(public name: string, public children: (File|Folder)[]) {}
}
function computeSize(node: File|Folder): number {
  if (node instanceof File) return node.size;
  let total = 0; for (const c of (node as Folder).children) total += computeSize(c);
  return total;
}
function print(node: File|Folder): void {
  if (node instanceof File) console.log(node.name);
  for (const c of (node instanceof Folder ? (node as Folder).children : [])) print(c);
}

